import datetime
import calendar
import bisect
from typing import List, Tuple, Set


def _parse_field(field: str, min_val: int, max_val: int, name: str) -> Tuple[List[int], bool]:
    """
    Parse one cron field and return a sorted list of values and a flag indicating
    whether the field was '*'.
    """
    items = field.split(',')
    values: Set[int] = set()
    is_all = False

    for item in items:
        if item == '':
            raise ValueError(f"empty item in {name} field")
        if item == '*':
            is_all = True
            values.update(range(min_val, max_val + 1))
        elif '/' in item:
            base, step_str = item.split('/')
            if not step_str.isdigit() or int(step_str) == 0:
                raise ValueError(f"invalid step in {name} field")
            step = int(step_str)

            if base == '*':
                start, end = min_val, max_val
            elif '-' in base:
                start_str, end_str = base.split('-')
                if not (start_str.isdigit() and end_str.isdigit()):
                    raise ValueError(f"invalid range in {name} field")
                start, end = int(start_str), int(end_str)
                if start > end:
                    raise ValueError(f"range {start}-{end} invalid in {name} field")
                if start < min_val or end > max_val:
                    raise ValueError(f"range {start}-{end} out of bounds in {name} field")
            else:
                raise ValueError(f"step without range in {name} field")

            values.update(range(start, end + 1, step))
        elif '-' in item:
            start_str, end_str = item.split('-')
            if not (start_str.isdigit() and end_str.isdigit()):
                raise ValueError(f"invalid range in {name} field")
            start, end = int(start_str), int(end_str)
            if start > end:
                raise ValueError(f"range {start}-{end} invalid in {name} field")
            if start < min_val or end > max_val:
                raise ValueError(f"range {start}-{end} out of bounds in {name} field")
            values.update(range(start, end + 1))
        else:
            if not item.isdigit():
                raise ValueError(f"invalid value '{item}' in {name} field")
            n = int(item)
            if n < min_val or n > max_val:
                raise ValueError(f"value {n} out of bounds in {name} field")
            values.add(n)

    if not values:
        raise ValueError(f"no valid values in {name} field")

    return sorted(values), is_all


def _month_last_day(month: int) -> int:
    """Return the maximum possible day for a month (ignoring year)."""
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    return 29  # February – 29 covers leap years


def _parse_cron(expr: str) -> Tuple[List[int], List[int], List[int], List[int], List[int],
                                   bool, bool, bool, bool, bool]:
    parts = expr.strip().split()
    if len(parts) != 5:
        raise ValueError("cron expression must have exactly five fields")

    minute_str, hour_str, dom_str, month_str, dow_str = parts

    minute_set, minute_all = _parse_field(minute_str, 0, 59, "minute")
    hour_set, hour_all = _parse_field(hour_str, 0, 23, "hour")
    dom_set, dom_all = _parse_field(dom_str, 1, 31, "day of month")
    month_set, month_all = _parse_field(month_str, 1, 12, "month")
    dow_set, dow_all = _parse_field(dow_str, 0, 7, "day of week")
    dow_set = {0 if d == 7 else d for d in dow_set}

    # Validate that the expression can fire at all
    if not dom_all:
        possible = False
        for m in month_set:
            max_day = _month_last_day(m)
            if any(d <= max_day for d in dom_set):
                possible = True
                break
        if not possible:
            raise ValueError("cron expression never fires")

    return (minute_set, hour_set, dom_set, month_set, dow_set,
            minute_all, hour_all, dom_all, month_all, dow_all)


def _day_matches(year: int, month: int, day: int,
                 dom_set: List[int], dow_set: List[int],
                 dom_all: bool, dow_all: bool) -> bool:
    """Return True if the date matches the day-of-month and day-of-week rules."""
    if dom_all:
        dom_match = True
    else:
        dom_match = day in dom_set

    dow = (datetime.date(year, month, day).weekday() + 1) % 7  # Sunday=0
    if dow_all:
        dow_match = True
    else:
        dow_match = dow in dow_set

    if dom_all and dow_all:
        return True
    if dom_all:
        return dow_match
    if dow_all:
        return dom_match
    return dom_match or dow_match


def next_fire(expr: str, after: datetime.datetime) -> datetime.datetime:
    """
    Return the next datetime that matches the cron expression `expr`
    strictly after the naive datetime `after`.
    """
    (minute_set, hour_set, dom_set, month_set, dow_set,
     minute_all, hour_all, dom_all, month_all, dow_all) = _parse_cron(expr)

    # Start from the next minute boundary strictly after `after`
    cand = after.replace(second=0, microsecond=0)
    if cand <= after:
        cand += datetime.timedelta(minutes=1)

    # Main loop – we always move forward in time
    while cand.year <= 3000:
        # ----- Month -----
        if cand.month not in month_set:
            idx = bisect.bisect_right(month_set, cand.month)
            if idx < len(month_set):
                cand = cand.replace(month=month_set[idx], day=1, hour=0, minute=0)
            else:
                cand = cand.replace(year=cand.year + 1, month=month_set[0], day=1, hour=0, minute=0)
            continue

        # ----- Day -----
        last_day = calendar.monthrange(cand.year, cand.month)[1]
        start_day = cand.day
        found_day = None
        for d in range(start_day, last_day + 1):
            if _day_matches(cand.year, cand.month, d,
                            dom_set, dow_set, dom_all, dow_all):
                found_day = d
                break

        if found_day is None:
            # No valid day in this month – move to next month
            idx = bisect.bisect_right(month_set, cand.month)
            if idx < len(month_set):
                cand = cand.replace(month=month_set[idx], day=1, hour=0, minute=0)
            else:
                cand = cand.replace(year=cand.year + 1, month=month_set[0], day=1, hour=0, minute=0)
            continue

        if found_day != cand.day:
            cand = cand.replace(day=found_day, hour=0, minute=0)
            continue

        # ----- Hour -----
        if cand.hour not in hour_set:
            idxh = bisect.bisect_right(hour_set, cand.hour)
            if idxh < len(hour_set):
                cand = cand.replace(hour=hour_set[idxh], minute=0)
                continue
            else:
                # No more hours this day – advance to next day
                next_day = None
                for d in range(cand.day + 1, last_day + 1):
                    if _day_matches(cand.year, cand.month, d,
                                    dom_set, dow_set, dom_all, dow_all):
                        next_day = d
                        break
                if next_day is not None:
                    cand = cand.replace(day=next_day, hour=hour_set[0], minute=0)
                    continue
                else:
                    # Advance month
                    idx = bisect.bisect_right(month_set, cand.month)
                    if idx < len(month_set):
                        cand = cand.replace(month=month_set[idx], day=1, hour=hour_set[0], minute=0)
                    else:
                        cand = cand.replace(year=cand.year + 1,
                                            month=month_set[0],
                                            day=1,
                                            hour=hour_set[0],
                                            minute=0)
                    continue

        # ----- Minute -----
        if cand.minute not in minute_set:
            idxm = bisect.bisect_right(minute_set, cand.minute)
            if idxm < len(minute_set):
                cand = cand.replace(minute=minute_set[idxm])
                continue
            else:
                # No more minutes this hour – advance to next hour
                idxh = bisect.bisect_right(hour_set, cand.hour)
                if idxh < len(hour_set):
                    cand = cand.replace(hour=hour_set[idxh], minute=0)
                    continue
                else:
                    # Advance day
                    next_day = None
                    for d in range(cand.day + 1, last_day + 1):
                        if _day_matches(cand.year, cand.month, d,
                                        dom_set, dow_set, dom_all, dow_all):
                            next_day = d
                            break
                    if next_day is not None:
                        cand = cand.replace(day=next_day, hour=hour_set[0], minute=0)
                        continue
                    else:
                        # Advance month
                        idx = bisect.bisect_right(month_set, cand.month)
                        if idx < len(month_set):
                            cand = cand.replace(month=month_set[idx], day=1, hour=hour_set[0], minute=0)
                        else:
                            cand = cand.replace(year=cand.year + 1,
                                                month=month_set[0],
                                                day=1,
                                                hour=hour_set[0],
                                                minute=0)
                        continue
        else:
            # Minute matches – check if we are strictly after `after`
            if cand > after:
                return cand
            # Need to find the next matching minute
            idxm = bisect.bisect_right(minute_set, cand.minute)
            if idxm < len(minute_set):
                cand = cand.replace(minute=minute_set[idxm])
                continue
            else:
                # Advance hour
                idxh = bisect.bisect_right(hour_set, cand.hour)
                if idxh < len(hour_set):
                    cand = cand.replace(hour=hour_set[idxh], minute=0)
                    continue
                else:
                    # Advance day
                    next_day = None
                    for d in range(cand.day + 1, last_day + 1):
                        if _day_matches(cand.year, cand.month, d,
                                        dom_set, dow_set, dom_all, dow_all):
                            next_day = d
                            break
                    if next_day is not None:
                        cand = cand.replace(day=next_day, hour=hour_set[0], minute=0)
                        continue
                    else:
                        # Advance month
                        idx = bisect.bisect_right(month_set, cand.month)
                        if idx < len(month_set):
                            cand = cand.replace(month=month_set[idx], day=1, hour=hour_set[0], minute=0)
                        else:
                            cand = cand.replace(year=cand.year + 1,
                                                month=month_set[0],
                                                day=1,
                                                hour=hour_set[0],
                                                minute=0)
                        continue

    raise ValueError("no fire time found before year 3000")
